import{_ as l,o as a,c as e,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2023-07-05","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2023-07-05","date":"2023-07-05T00:00:00.000Z","updated":"2023-07-06T00:00:00.000Z","tags":["Ceph","RGW重构","存储桶扩展","Lua包重载","Ceph RGW"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-07-05.md","filePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-07-05.md","lastUpdated":1780459816000}'),o={name:"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-07-05.md"};function r(n,t,s,p,u,_){return a(),e("div",null,[...t[0]||(t[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-扩展用户存储桶数量的讨论" tabindex="-1">会议主题：扩展用户存储桶数量的讨论 <a class="header-anchor" href="#会议主题-扩展用户存储桶数量的讨论" aria-label="Permalink to &quot;会议主题：扩展用户存储桶数量的讨论&quot;">​</a></h4><p><strong>主要议题：</strong></p><ul><li>当前的用户存储桶列表存储在单个 RADOS 对象的 omap 中，随着存储桶数量的增加，可能会影响性能。</li><li>讨论了 omap 的最大键数限制（200,000）及其对 RADOS 复制和恢复设计的影响。</li><li>提出了通过分片策略来解决存储桶数量增长的问题，但需要考虑排序和分页的需求。</li><li>讨论了是否需要为存储桶列表 API 增加排序和分页功能。</li></ul><p><strong>决定事项：</strong></p><ul><li>需要进一步研究和实现分片策略，以支持更大数量的存储桶。</li><li>需要评估和优化存储桶列表 API 的性能，考虑是否增加排序和分页功能。</li></ul><p><strong>后续行动计划：</strong></p><ul><li>继续研究和测试分片策略，确保其能够有效支持大量存储桶。</li><li>评估存储桶列表 API 的需求，考虑是否需要增加排序和分页功能。</li><li>增加文档说明，明确用户存储桶数量的限制和相关性能影响。</li></ul><h4 id="会议主题-lua包重载机制的改进" tabindex="-1">会议主题：Lua包重载机制的改进 <a class="header-anchor" href="#会议主题-lua包重载机制的改进" aria-label="Permalink to &quot;会议主题：Lua包重载机制的改进&quot;">​</a></h4><p><strong>主要议题：</strong></p><ul><li>当前 Lua 包重载需要重启 RADOS 网关（rgw），希望避免这种情况。</li><li>讨论了使用 watch notify 机制来实现无需重启的重载。</li><li>讨论了是否需要抽象出通知机制，以便未来支持其他存储后端。</li></ul><p><strong>决定事项：</strong></p><ul><li>需要进一步研究和实现 watch notify 机制，以支持 Lua 包的动态重载。</li><li>需要考虑抽象出通知机制，以便未来支持其他存储后端。</li></ul><p><strong>后续行动计划：</strong></p><ul><li>继续研究和测试 watch notify 机制，确保其能够有效支持 Lua 包的动态重载。</li><li>考虑抽象出通知机制，以便未来支持其他存储后端。</li></ul><h4 id="其他议题" tabindex="-1">其他议题： <a class="header-anchor" href="#其他议题" aria-label="Permalink to &quot;其他议题：&quot;">​</a></h4><ul><li>讨论了 Bloom 过滤器的最新进展，但没有新的更新。</li></ul><p><strong>会议总结：</strong></p><ul><li>本次会议主要讨论了如何扩展用户存储桶数量和改进 Lua 包重载机制，确定了后续的研究和开发方向。</li><li>需要继续关注和研究相关技术细节，确保解决方案的有效性和性能。</li></ul><p><strong>下次会议预告：</strong></p><ul><li>下次会议将继续讨论和评估本次会议确定的方案，并根据进展调整后续行动计划。</li></ul>',21)])])}const c=l(o,[["render",r]]);export{g as __pageData,c as default};
